      (entry) => `${entry.isDirectory ? "[DIR]" : "[FILE]"} ${entry.name.padEnd(30)} ${entry.isDirectory ? "" : formatSize(entry.size).padStart(10)}`,
    );
    const totalFiles = detailedEntries.filter((e) => !e.isDirectory).length;
    const totalDirs = detailedEntries.filter((e) => e.isDirectory).length;
    const totalSize = detailedEntries.reduce((sum, entry) => sum + (entry.isDirectory ? 0 : entry.size), 0);
    const summary = ["", `Total: ${totalFiles} files, ${totalDirs} directories`, `Combined size: ${formatSize(totalSize)}`];
    const text = [...formattedEntries, ...summary].join("\n");
    return {
      content: [{ type: "text" as const, text }],
      structuredContent: { content: text },
    };
  },
);

server.registerTool(
  "directory_tree",
  {
    title: "Directory Tree",
    description:
      "Get a recursive tree view of files and directories as a JSON structure. " +
      "Each entry includes 'name', 'type' (file/directory), and 'children' for directories. " +
      "Files have no children array, while directories always have a children array (which may be empty). " +
      "The output is formatted with 2-space indentation for readability. Only works within allowed directories.",
    inputSchema: {
      path: z.string(),
      excludePatterns: z.array(z.string()).optional().default([]),
    },
    outputSchema: { content: z.string() },
    annotations: { readOnlyHint: true, openWorldHint: false },
  },
  async (args: z.infer<typeof DirectoryTreeArgsSchema>) => {
    const rootPath = args.path;
    async function buildTree(currentPath: string, excludePatterns: string[] = []): Promise<Array<Record<string, unknown>>> {
      const validPath = await validatePath(currentPath);
      const entries = await fs.readdir(validPath, { withFileTypes: true });
      const result: Array<Record<string, unknown>> = [];
      for (const entry of entries) {
        const relativePath = path.relative(rootPath, path.join(currentPath, entry.name));
        const shouldExclude = excludePatterns.some((pattern) => {
          if (pattern.includes("*")) {
            return minimatch(relativePath, pattern, { dot: true });
          }
          return (
            minimatch(relativePath, pattern, { dot: true }) ||
            minimatch(relativePath, `**/${pattern}`, { dot: true }) ||
            minimatch(relativePath, `**/${pattern}/**`, { dot: true })
          );
        });
        if (shouldExclude) continue;
        const entryData: Record<string, unknown> = {
          name: entry.name,
          type: entry.isDirectory() ? "directory" : "file",
        };
        if (entry.isDirectory()) {
          entryData.children = await buildTree(path.join(currentPath, entry.name), excludePatterns);
        }
        result.push(entryData);
      }
      return result;
    }
    const treeData = await buildTree(rootPath, args.excludePatterns);
    const text = JSON.stringify(treeData, null, 2);
    return {
      content: [{ type: "text" as const, text }],
      structuredContent: { content: text },
    };
  },
);

