// ---------------------------------------------------------------------------
// Roots handler — allows the MCP client to dynamically update directories
// ---------------------------------------------------------------------------
async function updateAllowedDirectoriesFromRoots(requestedRoots: unknown[]): Promise<void> {
  const validatedRootDirs = await getValidRootDirectories(requestedRoots as { uri: string }[]);
  if (validatedRootDirs.length > 0) {
    accessibleDirectories.length = 0;
    accessibleDirectories.push(...validatedRootDirs);
    setAllowedDirectories(accessibleDirectories);
    log(`Updated allowed directories from MCP roots: ${validatedRootDirs.length} valid directories`);
  } else {
    log("No valid root directories provided by client");
  }
}

server.server.setNotificationHandler(RootsListChangedNotificationSchema, async () => {
  try {
    const response = await server.server.listRoots();
    if (response && "roots" in response) {
      await updateAllowedDirectoriesFromRoots(response.roots);
    }
  } catch (error) {
    log(`Failed to request roots from client: ${error instanceof Error ? error.message : String(error)}`);
  }
});

server.server.oninitialized = async () => {
  const clientCapabilities = server.server.getClientCapabilities();
  if (clientCapabilities?.roots) {
    try {
      const response = await server.server.listRoots();
      if (response && "roots" in response) {
        await updateAllowedDirectoriesFromRoots(response.roots);
      } else {
        log("Client returned no roots set, keeping current settings");
      }
    } catch (error) {
      log(`Failed to request initial roots from client: ${error instanceof Error ? error.message : String(error)}`);
    }
  } else {
    if (accessibleDirectories.length > 0) {
      log(`Client does not support MCP Roots, using allowed directories set from server args: ${accessibleDirectories.join(", ")}`);
    } else {
      throw new Error(
        `Server cannot operate: No allowed directories available. Server was started without command-line directories and client either does not support MCP roots protocol or provided empty roots.`,
      );
    }
  }
};

// ---------------------------------------------------------------------------
// Start server
// ---------------------------------------------------------------------------
async function main(): Promise<void> {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  log("Secure MCP Filesystem Server running on stdio");
  if (accessibleDirectories.length === 0) {
    log("Started without allowed directories - waiting for client to provide roots via MCP protocol");
  }
}

main().catch((error) => {
  console.error("Fatal error running server:", error);
  process.exit(1);
});

