    const timer = setTimeout(() => {
      child.kill();
      reject(new Error(`timed out waiting for response from ${script}`));
    }, 8000);
    child.stdout.on("data", (d) => {
      out += d.toString();
      const lines = out.split("\n").filter((l) => l.trim());
      if (!initResolved && lines.length >= 1) {
        // Got the initialize response; send the second request
        initResolved = true;
        child.stdin.write(JSON.stringify(secondRequest) + "\n");
      }
      if (initResolved && lines.length >= 2) {
        // Got the second response
        clearTimeout(timer);
        child.kill();
        try {
